import React, { useState } from 'react';
import * as Collapsible from '@radix-ui/react-collapsible';
import { ChevronDown, ChevronUp } from '@hexa-ui/icons';
import { ExpandableSectionType } from './ExpandableSection.types';
import {
  StyledCard,
  StyledContent,
  StyledHeader,
  StyledIconButton,
} from './ExpandableSection.styles';
import { Heading } from '../typography';
import { Divider } from '../divider';

const ExpandableSectionComponent = (
  {
    withDivider = false,
    headerText,
    open,
    defaultOpen,
    children,
    triggerTestId,
    onOpenChange,
    css,
    ...props
  }: ExpandableSectionType,
  forwardedRef: React.ForwardedRef<HTMLDivElement>
): JSX.Element => {
  const [isOpen, setIsOpen] = useState(defaultOpen);

  function handleOpenChange(openValue: boolean) {
    setIsOpen((prevState) => !prevState);

    if (onOpenChange) {
      onOpenChange(openValue);
    }
  }

  return (
    <Collapsible.Root
      ref={forwardedRef}
      open={open}
      defaultOpen={defaultOpen}
      // eslint-disable-next-line react/jsx-no-bind
      onOpenChange={handleOpenChange}
      {...props}
    >
      <StyledCard border="medium" elevated="medium" css={css}>
        <StyledHeader>
          <Heading size="H5">{headerText}</Heading>
          <Collapsible.Trigger asChild data-testid={triggerTestId}>
            <StyledIconButton
              icon={isOpen || open ? ChevronUp : ChevronDown}
              variant="inherit"
              size="medium"
            />
          </Collapsible.Trigger>
        </StyledHeader>
        <Collapsible.Content>
          {withDivider && <Divider orientation="horizontal" css={{ margin: '$4 0 $2 0' }} />}
          <StyledContent>{children}</StyledContent>
        </Collapsible.Content>
      </StyledCard>
    </Collapsible.Root>
  );
};

export const ExpandableSection = React.forwardRef(ExpandableSectionComponent);
export default ExpandableSection;
